sys_script_client.script:
function onSubmit() {
   var course = g_form.getValue('course');
   var date = g_form.getValue('training_date');

   var gaSchedule = new GlideAjax("x_1131775_traini_0.ScheduleValidation");
   gaSchedule.addParam('sysparm_name','checkDuplicate');
   gaSchedule.addParam('sysparm_course',course);
   gaSchedule.addParam('sysparm_date',date);
   gaSchedule.addParam('sysparm_sys_id',g_form.getUniqueValue());

   var result = gaSchedule.getXMLWait();
   var response = result.documentElement.getAttribute('answer');

   if (response === 'true') {
	alert('Já existe um treinamento deste curso nesta data');
	//impedir o envio do formulário
	return false; 
   }

   return true;
}
